package campfire.richtext;

import static org.junit.jupiter.api.Assertions.assertTrue;

import campfire.rails.Json;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.junit.jupiter.api.Test;

/// Differential test against the Rails pipeline (`richtext-corpus/expected.json`, generated by the
/// Rust port's reference tools in the Rails image), plus security properties of every output.
@SuppressWarnings("unchecked")
class RichTextCorpusTest {
    static final Map<String, Object> CORPUS = load();

    static Map<String, Object> load() {
        try (var in = RichTextCorpusTest.class.getResourceAsStream("/richtext-corpus/expected.json")) {
            return (Map<String, Object>) Json.parse(new String(in.readAllBytes(), StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static final class TestResolver implements RichText.Resolver {
        final List<RichText.MentionUser> users = new ArrayList<>();
        final List<Map<String, Object>> signed;
        final List<Long> rooms;

        TestResolver() {
            for (var u : (List<Map<String, Object>>) CORPUS.get("users")) {
                users.add(new RichText.MentionUser((Long) u.get("id"), (String) u.get("name"), (String) u.get("title"),
                    (String) u.get("attachable_sgid"), (String) u.get("user_path"), (String) u.get("avatar_path")));
            }
            signed = (List<Map<String, Object>>) CORPUS.get("signed");
            rooms = (List<Long>) CORPUS.get("rooms");
        }

        RichText.MentionUser user(long id) {
            return users.stream().filter(u -> u.id() == id).findFirst().orElse(null);
        }

        @Override
        public RichText.MentionUser locateSigned(String sgid) {
            for (var s : signed) {
                if (s.get("sgid").equals(sgid) && "User".equals(s.get("model")) && Boolean.TRUE.equals(s.get("exists"))) return user((Long) s.get("id"));
            }
            return null;
        }

        @Override
        public RichText.MentionUser findGid(String gid) {
            if (!gid.startsWith("gid://")) return null;
            String rest = gid.substring(6);
            int slash = rest.indexOf('/');
            if (slash < 0) return null;
            rest = rest.substring(slash + 1).split("\\?")[0];
            String[] parts = rest.split("/", 2);
            if (parts.length < 2 || !parts[0].equals("User")) return null;
            try {
                return user(Long.parseLong(parts[1]));
            } catch (NumberFormatException e) {
                return null;
            }
        }
    }

    static String normalized(String html) {
        var out = new StringBuilder();
        normalizeInto(Html.parseFragment(html), out);
        return out.toString();
    }

    static void normalizeInto(Node node, StringBuilder out) {
        for (Node child : node.childNodes()) {
            if (child instanceof TextNode t) {
                String collapsed = String.join(" ", t.getWholeText().trim().split("\\s+"));
                out.append(collapsed);
            } else if (child instanceof Element e) {
                var attrs = new ArrayList<String>();
                for (Attribute a : e.attributes()) attrs.add(a.getKey() + "=" + a.getValue());
                attrs.sort(null);
                out.append('<').append(e.normalName()).append(attrs).append('>');
                normalizeInto(e, out);
                out.append("</").append(e.normalName()).append('>');
            }
        }
    }

    static final Set<String> DANGEROUS = Set.of("script", "style", "iframe", "frame", "frameset", "object", "embed", "applet", "base", "meta",
        "link", "form", "input", "button", "textarea", "select", "svg", "math", "template", "noscript", "xmp", "plaintext", "noembed");

    static List<String> violations(String html) {
        var out = new ArrayList<String>();
        for (Element e : Html.parseFragment(html).getAllElements()) {
            if (e.normalName().equals("body")) continue;
            if (DANGEROUS.contains(e.normalName())) out.add("<" + e.normalName() + ">");
            if (!Sanitizer.AUTO_LINK.tags().contains(e.normalName())) out.add("<" + e.normalName() + "> not allowed");
            for (Attribute a : e.attributes()) {
                String name = a.getKey().toLowerCase();
                if (!Sanitizer.AUTO_LINK.attributes().contains(name) && !name.equals("target")) out.add(name + " on " + e.normalName());
                if (name.startsWith("on")) out.add(name);
                String v = a.getValue().replaceAll("[\\p{Cntrl}\\s]", "").toLowerCase();
                if ((name.equals("href") || name.equals("src")) && (v.startsWith("javascript:") || v.startsWith("vbscript:"))) out.add(name + "=" + v);
            }
        }
        return out;
    }

    @Test
    void matchesRails() {
        var resolver = new TestResolver();
        int exact = 0, dom = 0, plainExact = 0, mentionedExact = 0, total = 0, plainTotal = 0;
        var mismatches = new ArrayList<String>();
        var plainMismatches = new ArrayList<String>();
        var security = new ArrayList<String>();
        for (var c : (List<Map<String, Object>>) CORPUS.get("cases")) {
            var ctx = new RichText.Context(resolver, (String) c.get("host"));
            String body = (String) c.get("body");
            String name = (String) c.get("name");
            String actual = RichText.presentation(body, ctx);
            security.addAll(violations(actual).stream().map(v -> name + ": " + v).toList());
            if (c.get("presentation") instanceof Map<?, ?> p && p.get("ok") instanceof String expected) {
                total++;
                if (expected.equals(actual)) exact++;
                else if (normalized(expected).equals(normalized(actual))) dom++;
                else mismatches.add(name + "\n  expected: " + expected + "\n  actual:   " + actual);
            }
            if (c.get("plain_text") instanceof Map<?, ?> p && p.get("ok") instanceof String expected) {
                plainTotal++;
                String plain = RichText.plainText(body, ctx);
                if (expected.equals(plain)) plainExact++;
                else plainMismatches.add(name + "\n  expected: " + expected + "\n  actual:   " + plain);
            }
            if (c.get("mentioned") instanceof Map<?, ?> p && p.get("ok") instanceof List<?> expected) {
                var ids = RichText.mentionedUserIds(body, ctx);
                var expectedIds = new ArrayList<Long>();
                for (Object o : expected) expectedIds.add(o instanceof Map<?, ?> m ? (Long) m.get("id") : (Long) o);
                if (expectedIds.equals(ids)) mentionedExact++;
            }
        }
        System.out.printf("presentation: %d exact, %d DOM-equal, %d different of %d%n", exact, dom, mismatches.size(), total);
        System.out.printf("plain text: %d of %d exact; mentions: %d exact%n", plainExact, plainTotal, mentionedExact);
        mismatches.forEach(m -> System.out.println("MISMATCH " + m.lines().findFirst().orElse("")));
        plainMismatches.stream().limit(10).forEach(m -> System.out.println("PLAIN " + m));
        security.forEach(s -> System.out.println("SECURITY " + s));
        assertTrue(security.isEmpty(), "security violations");
    }
}
